/**
 * Renders the map with sigma.js (WebGL): pan, zoom, hover, hit testing and label placement come
 * from sigma. This component maps the module's state (search matches, selection, unread counts,
 * avatars) onto sigma's node reducer and wires up clicks, camera flights and the tooltip.
 */

import { useEffect, useLayoutEffect, useRef, useState, type JSX, type ReactNode } from "react";
import Sigma from "sigma";
import type { NodeLabelDrawingFunction } from "sigma/rendering";
import type { Settings } from "sigma/settings";

import type { DistrictId } from "../districts";
import type { MapGraph, NodeAttrs } from "../views";
import { flyTo, prefersReducedMotion, type Flight, type SavedCamera } from "./camera";
import { mix, premultiplied, withAlpha } from "./colour";
import { buildPrograms } from "./programs";
import type { ColourMode } from "../settings";
import { districtColour, readTheme, type Theme } from "./theme";
import { placeTooltip } from "./tooltip";

/** Where the camera should go: a room or space by id, a node or line by key (a district, a group), or everything. */
export interface FocusTarget {
    roomId?: string;
    nodeKey?: string;
    /** The tube map's line (a space's id, or a group's key). */
    line?: string;
    district?: DistrictId;
    overview?: boolean;
    /** Right up to a room, as when walking into it. */
    close?: boolean;
    /** Straight back to a saved camera, without a flight. */
    camera?: SavedCamera;
    nonce: number;
}

export interface SigmaMapProps {
    /** Read once: the map is built when it opens. */
    graph: MapGraph;
    /** Room ids matching the search; null when there is no query. */
    matches: Set<string> | null;
    selected?: string;
    current?: string;
    focus: FocusTarget | null;
    label: string;
    onActivate(roomId: string): void;
    /** `blob:` URL of a loaded avatar. */
    avatarUrl?(mxc: string | undefined): string | undefined;
    /** Average colour of a loaded avatar. */
    avatarColour?(mxc: string | undefined): string | undefined;
    /** Changes when more avatars have loaded. */
    avatarVersion?: number;
    /** Content of the tooltip shown while the pointer is over a node. */
    tooltip?(node: NodeAttrs): ReactNode;
    /** Where the camera starts; the whole map when missing. Read once. */
    camera?: SavedCamera;
    /** Without a saved camera: start on this room and zoom out from it. Read once. */
    introRoom?: string;
    colours: ColourMode;
    /** Zooms on opening and leaving (the setting, unless the system asks for less motion). */
    animate: boolean;
    /** False while the map is kept ready but hidden: nothing is drawn then. */
    visible: boolean;
    /** Changes when unread counts in `graph` were updated in place. */
    countsVersion?: number;
    /** Rooms that just got something new: they light up once. */
    flash?: { rooms: Set<string>; nonce: number };
    onCameraChange?(camera: SavedCamera): void;
    /** Drawn over the map (the legend). */
    children?: ReactNode;
}

/** Moving from one node to the next doesn't blink the tooltip off and on. */
const TIP_HIDE_MS = 120;
/** On opening, how long the map may stay hidden while the first avatars become textures. */
const REVEAL_WAIT_MS = 250;
/** Dot grid spacing on screen, kept within [GRID, 2 × GRID) at any zoom. */
const GRID = 24;
/** The camera showing the whole map. */
const OVERVIEW = { x: 0.5, y: 0.5, ratio: 1 };
/** One pulse of a room that mentions you. */
const PULSE_MS = 1600;
/** Rooms that mention you stay findable at any zoom: their beacon is never smaller than this. */
const BEACON_MIN_RADIUS = 6;
/** A room with a new message lights up this long. */
const FLASH_MS = 1400;
/** On opening, how long the map shows your room before zooming out. */
const INTRO_PAUSE_MS = 120;

export function SigmaMap(props: SigmaMapProps): JSX.Element {
    const containerRef = useRef<HTMLDivElement>(null);
    const propsRef = useRef(props);
    propsRef.current = props;
    const sigmaRef = useRef<Sigma<NodeAttrs> | null>(null);
    const flightRef = useRef<Flight | null>(null);
    const tipRef = useRef<HTMLDivElement>(null);
    const beaconRef = useRef<HTMLCanvasElement>(null);
    const lastTip = useRef<ReactNode>(null);
    const pointer = useRef({ x: 0, y: 0 });
    const [hovered, setHovered] = useState<NodeAttrs | null>(null);
    const [ready, setReady] = useState(false);
    const anyUnreadRef = useRef(false);
    /** Room id → when it started lighting up. */
    const flashes = useRef(new Map<string, number>());
    const loop = useRef<{ refresh(): void; wake(): void } | null>(null);

    const fly = (target: { x: number; y: number; ratio: number }): void => {
        const sigma = sigmaRef.current;
        if (!sigma) return;
        flightRef.current?.cancel();
        flightRef.current = flyTo(sigma.getCamera(), target);
    };

    useEffect(() => {
        const container = containerRef.current!;
        const theme = readTheme();
        let sigma: Sigma<NodeAttrs> | undefined;
        let programs: ReturnType<typeof buildPrograms>;
        try {
            const { drawLabel, drawHover } = labelDrawers(theme, () => propsRef.current.colours);
            programs = buildPrograms(drawLabel, drawHover);
            sigma = new Sigma(props.graph, container, {
                ...settings(theme, propsRef, anyUnreadRef),
                ...programs.settings,
            } as Partial<Settings<NodeAttrs>>);
        } catch (e) {
            // No WebGL (or a test environment): the list still works.
            console.warn("[space-room-map] Can't render the map", e);
            setReady(true);
            return;
        }
        sigmaRef.current = sigma;
        fitCircles(sigma);
        const introNode = !props.camera && props.animate && props.introRoom ? nodeOfRoom(sigma, props.introRoom) : undefined;
        if (props.camera) sigma.getCamera().setState(props.camera);
        // Zoomed in on the room you're in, then out to everything once the map shows.
        else if (introNode) sigma.getCamera().setState(focusState(sigma, introNode));
        sigma.getCamera().on("updated", ({ x, y, ratio }) => propsRef.current.onCameraChange?.({ x, y, ratio }));

        // Show the map once the first avatars are textures, so they don't pop in a moment later.
        let revealTimer: ReturnType<typeof setTimeout> | undefined;
        const reveal = (): void => {
            clearTimeout(revealTimer);
            programs.textures?.off("newTexture", onTexture);
            setReady(true);
            if (introNode) setTimeout(() => fly(OVERVIEW), INTRO_PAUSE_MS);
        };
        const onTexture = (): void => void requestAnimationFrame(reveal);
        const hasAvatars = sigma.getGraph().someNode((_, a) => Boolean(propsRef.current.avatarUrl?.(a.avatar)));
        if (hasAvatars && programs.textures) {
            programs.textures.on("newTexture", onTexture);
            revealTimer = setTimeout(reveal, REVEAL_WAIT_MS);
        } else {
            reveal();
        }

        // Rooms that mention you pulse, with their count, on a canvas of their own: redrawing
        // sigma's thousands of labels every frame would be too slow.
        const pulse = !prefersReducedMotion() && !theme.highContrast;
        const findMentions = (): string[] => sigma.getGraph().filterNodes((_, a) => !a.container && a.highlight > 0);
        let mentions = findMentions();
        const animating = (): boolean => propsRef.current.visible && ((pulse && mentions.length > 0) || flashes.current.size > 0);
        let beaconFrame = 0;
        const drawBeacons = (): void => {
            beaconFrame = 0;
            const canvas = beaconRef.current;
            const ctx = canvas?.getContext("2d");
            if (!canvas || !ctx) return;
            const w = container.clientWidth;
            const h = container.clientHeight;
            const dpr = window.devicePixelRatio || 1;
            if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
                canvas.width = Math.round(w * dpr);
                canvas.height = Math.round(h * dpr);
            }
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            ctx.clearRect(0, 0, w, h);
            const now = performance.now();
            const phase = pulse ? (now % PULSE_MS) / PULSE_MS : 0;
            const { matches } = propsRef.current;
            for (const key of mentions) {
                const a = sigma.getGraph().getNodeAttributes(key);
                const d = sigma.getNodeDisplayData(key);
                if (!d || (matches && !matches.has(a.roomId ?? ""))) continue;
                const p = sigma.framedGraphToViewport(d);
                const r = Math.max(BEACON_MIN_RADIUS, sigma.scaleSize(d.size));
                if (p.x < -r - 40 || p.y < -r - 40 || p.x > w + r + 40 || p.y > h + r + 40) continue;
                ctx.lineWidth = 2.5;
                ctx.strokeStyle = theme.highlight;
                ctx.globalAlpha = pulse ? (1 - phase) * 0.8 : 0.8;
                ctx.beginPath();
                ctx.arc(p.x, p.y, r + 3 + phase * 14, 0, Math.PI * 2);
                ctx.stroke();
                ctx.globalAlpha = 1;
                drawBadge(ctx, p.x + r * 0.72, p.y - r * 0.72, a.highlight, theme.highlight, theme);
            }
            // New messages: one ring that grows and fades, around every place the room is shown.
            for (const [roomId, start] of flashes.current) {
                const t = (now - start) / FLASH_MS;
                if (t >= 1) {
                    flashes.current.delete(roomId);
                    continue;
                }
                for (const key of roomNodes.get(roomId) ?? []) {
                    const a = sigma.getGraph().getNodeAttributes(key);
                    const d = sigma.getNodeDisplayData(key);
                    if (!d) continue;
                    const p = sigma.framedGraphToViewport(d);
                    const r = Math.max(BEACON_MIN_RADIUS, sigma.scaleSize(d.size));
                    if (p.x < -r - 60 || p.y < -r - 60 || p.x > w + r + 60 || p.y > h + r + 60) continue;
                    const ease = 1 - Math.pow(1 - t, 3);
                    ctx.lineWidth = 3;
                    ctx.strokeStyle = a.highlight ? theme.highlight : theme.unread;
                    ctx.globalAlpha = (1 - t) * 0.9;
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, r + 2 + ease * 28, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.globalAlpha = 1;
                }
            }
            if (animating()) beaconFrame = requestAnimationFrame(drawBeacons);
        };
        const roomNodes = new Map<string, string[]>();
        sigma.getGraph().forEachNode((key, a) => {
            if (a.roomId && !a.container) roomNodes.set(a.roomId, [...(roomNodes.get(a.roomId) ?? []), key]);
        });
        loop.current = {
            // Counts changed in the graph: mentions may have come or gone.
            refresh: () => {
                mentions = findMentions();
                anyUnreadRef.current = hasUnread(sigma.getGraph());
                loop.current?.wake();
            },
            wake: () => {
                if (!beaconFrame && animating()) beaconFrame = requestAnimationFrame(drawBeacons);
                else if (!beaconFrame) drawBeacons();
            },
        };
        anyUnreadRef.current = hasUnread(sigma.getGraph());
        if (animating()) beaconFrame = requestAnimationFrame(drawBeacons);

        // The dot grid moves and scales with the camera, like a surface the map lies on.
        sigma.on("afterRender", () => {
            if (!beaconFrame && (mentions.length || flashes.current.size)) drawBeacons();
            const origin = sigma.framedGraphToViewport({ x: 0, y: 0 });
            let size = GRID / sigma.getCamera().ratio;
            while (size >= GRID * 2) size /= 2;
            while (size < GRID) size *= 2;
            container.style.setProperty("--srm-grid-size", `${size}px`);
            container.style.setProperty("--srm-grid-x", `${origin.x % size}px`);
            container.style.setProperty("--srm-grid-y", `${origin.y % size}px`);
        });

        let hideTimer: ReturnType<typeof setTimeout> | undefined;
        sigma.on("enterNode", ({ node, event }) => {
            clearTimeout(hideTimer);
            container.style.cursor = "pointer";
            setHovered(sigma.getGraph().getNodeAttributes(node));
            placeTip(event.x, event.y);
        });
        sigma.on("leaveNode", () => {
            container.style.cursor = "";
            hideTimer = setTimeout(() => setHovered(null), TIP_HIDE_MS);
        });
        // The tooltip follows the pointer, so it stays near it even on a space circle that fills the view.
        const onPointerMove = (ev: MouseEvent): void => {
            const rect = container.getBoundingClientRect();
            placeTip(ev.clientX - rect.left, ev.clientY - rect.top);
        };
        const onPointerLeave = (): void => setHovered(null);
        // The user takes over the camera.
        const stopFlight = (): void => flightRef.current?.cancel();
        container.addEventListener("mousemove", onPointerMove);
        container.addEventListener("mouseleave", onPointerLeave);
        container.addEventListener("wheel", stopFlight, { passive: true });
        container.addEventListener("mousedown", stopFlight);
        container.addEventListener("touchstart", stopFlight, { passive: true });

        sigma.on("clickNode", ({ node }) => {
            const a = sigma.getGraph().getNodeAttributes(node);
            if (a.container) {
                // A space circle zooms in first; once it fills the view, a click opens its home.
                const target = focusState(sigma, node);
                if (sigma.getCamera().ratio > target.ratio * 1.3 || !a.roomId) {
                    fly(target);
                    return;
                }
            }
            if (a.roomId) propsRef.current.onActivate(a.roomId);
        });
        sigma.on("doubleClickNode", (e) => e.preventSigmaDefault());
        sigma.on("clickStage", () => fly(OVERVIEW));

        return () => {
            clearTimeout(revealTimer);
            clearTimeout(hideTimer);
            cancelAnimationFrame(beaconFrame);
            programs.textures?.off("newTexture", onTexture);
            flightRef.current?.cancel();
            container.removeEventListener("mousemove", onPointerMove);
            container.removeEventListener("mouseleave", onPointerLeave);
            container.removeEventListener("wheel", stopFlight);
            container.removeEventListener("mousedown", stopFlight);
            container.removeEventListener("touchstart", stopFlight);
            sigma.kill();
            sigmaRef.current = null;
            loop.current = null;
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Search, selection, current room, avatars and colours only change how nodes look.
    useEffect(() => {
        sigmaRef.current?.refresh({ skipIndexation: true });
    }, [props.matches, props.selected, props.current, props.avatarVersion, props.colours]);

    useEffect(() => {
        if (props.countsVersion) loop.current?.refresh();
    }, [props.countsVersion]);

    useEffect(() => {
        if (!props.flash) return;
        const now = performance.now();
        for (const id of props.flash.rooms) flashes.current.set(id, now);
        loop.current?.wake();
    }, [props.flash]);

    // Shown again after being kept hidden: the window may have changed size meanwhile.
    useEffect(() => {
        const sigma = sigmaRef.current;
        if (!props.visible || !sigma) return;
        sigma.resize();
        sigma.refresh({ skipIndexation: true });
        loop.current?.wake();
    }, [props.visible]);

    useEffect(() => {
        const sigma = sigmaRef.current;
        const focus = props.focus;
        if (!sigma || !focus) return;
        if (focus.camera) {
            flightRef.current?.cancel();
            sigma.getCamera().setState(focus.camera);
            return;
        }
        if (focus.overview) return fly(OVERVIEW);
        const node = focus.nodeKey && sigma.getGraph().hasNode(focus.nodeKey) ? focus.nodeKey : focus.roomId ? nodeOfRoom(sigma, focus.roomId) : undefined;
        if (node) fly(focus.close ? closeState(sigma, node) : focusState(sigma, node));
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [props.focus]);

    // The tooltip's size is only known once its content has rendered.
    useLayoutEffect(() => placeTip(pointer.current.x, pointer.current.y), [hovered]); // eslint-disable-line react-hooks/exhaustive-deps

    const placeTip = (x: number, y: number): void => {
        pointer.current = { x, y };
        placeTooltip(tipRef.current, containerRef.current, x, y);
    };
    const tip = hovered && props.tooltip?.(hovered);
    // Kept while fading out.
    if (tip) lastTip.current = tip;

    return (
        <div className="srm-stage">
            <div ref={containerRef} className={`srm-map${ready ? " srm-map--ready" : ""}`} role="img" aria-label={props.label} />
            <canvas ref={beaconRef} className="srm-beacons" aria-hidden="true" />
            {/* Pointer-only: keyboard users get the same details in the list. */}
            <div ref={tipRef} className="srm-tooltip" data-visible={Boolean(tip)} aria-hidden="true">
                {tip || lastTip.current}
            </div>
            {props.children}
        </div>
    );
}

function nodeOfRoom(sigma: Sigma<NodeAttrs>, roomId: string): string | undefined {
    let node: string | undefined;
    sigma.getGraph().forEachNode((key, a) => {
        if (!node && a.roomId === roomId) node = key;
    });
    return node;
}

function hasUnread(graph: MapGraph): boolean {
    return graph.someNode((_, a) => !a.container && (a.unread > 0 || a.highlight > 0));
}

/** Right up to a node: it fills most of the view. */
function closeState(sigma: Sigma<NodeAttrs>, node: string): { x: number; y: number; ratio: number } {
    const display = sigma.getNodeDisplayData(node)!;
    const { x, y } = sigma.getCustomBBox() ?? sigma.getBBox();
    const extent = Math.max(x[1] - x[0], y[1] - y[0]);
    const size = sigma.getGraph().getNodeAttribute(node, "size");
    return { x: display.x, y: display.y, ratio: Math.max(0.0005, ((2 * size) / extent) * 1.6) };
}

/** Camera state that shows a node: a space fills the view; a room shows with its space around it. */
function focusState(sigma: Sigma<NodeAttrs>, node: string): { x: number; y: number; ratio: number } {
    const graph = sigma.getGraph();
    const display = sigma.getNodeDisplayData(node)!;
    const a = graph.getNodeAttributes(node);
    // Graph units → camera ratio, relative to the whole map's extent.
    const { x, y } = sigma.getCustomBBox() ?? sigma.getBBox();
    const extent = Math.max(x[1] - x[0], y[1] - y[0]);
    const ratioFor = (radius: number, fill: number): number => Math.max(0.0005, ((2 * radius) / extent) * fill);
    if (a.container) return { x: display.x, y: display.y, ratio: ratioFor(a.size, 1.15) };
    const parentKey = node.slice(0, node.lastIndexOf("/"));
    if (parentKey && graph.hasNode(parentKey)) {
        const parent = graph.getNodeAttributes(parentKey);
        const ratio = ratioFor(parent.size, 1.15);
        // A room that would be tiny inside its whole space gets a closer look.
        if (ratio <= ratioFor(a.size, 10)) {
            const p = sigma.getNodeDisplayData(parentKey)!;
            return { x: p.x, y: p.y, ratio };
        }
    }
    return { x: display.x, y: display.y, ratio: ratioFor(a.size, 8) };
}

/**
 * Frames the whole packing. sigma fits the camera to node centres only, so with few spaces the
 * outer circles would reach past the edges.
 */
function fitCircles(sigma: Sigma<NodeAttrs>): void {
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    sigma.getGraph().forEachNode((_, a) => {
        x0 = Math.min(x0, a.x - a.size);
        x1 = Math.max(x1, a.x + a.size);
        y0 = Math.min(y0, a.y - a.size);
        y1 = Math.max(y1, a.y + a.size);
    });
    if (x0 < x1) sigma.setCustomBBox({ x: [x0, x1], y: [y0, y1] });
}

function settings(theme: Theme, propsRef: { current: SigmaMapProps }, anyUnreadRef: { current: boolean }): Partial<Settings<NodeAttrs>> {
    const veil = premultiplied(theme.bg, 0.6);
    return {
        allowInvalidContainer: true,
        renderEdgeLabels: false,
        zIndex: true,
        stagePadding: 40,
        labelFont: theme.font,
        labelSize: 13,
        labelWeight: "500",
        labelColor: { color: theme.text },
        // Labels decide themselves whether they're big enough (see labelDrawers).
        labelRenderedSizeThreshold: 0,
        // Sizes are in graph units and scale exactly with zoom, as circle packing needs.
        itemSizesReference: "positions",
        zoomToSizeRatioFunction: (ratio) => ratio,
        minCameraRatio: 0.0005,
        maxCameraRatio: 3,
        nodeReducer: (_, a) => {
            const { matches, selected, current, avatarUrl, avatarColour, colours } = propsRef.current;
            const anyUnread = anyUnreadRef.current;
            const byDistrict = colours === "district";
            const lit = !matches || (a.roomId !== undefined && matches.has(a.roomId));
            // Every name is drawn, fading in with size: no labels popping in and out while zooming.
            const out: Record<string, unknown> = { ...a, forceLabel: true };

            if (a.container) {
                // Tinted with the space's avatar (or its own colour), lighter at every other depth.
                // By district: the district's colour all the way in, so you know where you are.
                const tint = byDistrict
                    ? districtColour(theme, a.district).fg
                    : a.kind === "group"
                      ? theme.hover
                      : (avatarColour?.(a.avatar) ?? theme.decorative[colourIndex(a.roomId ?? a.label)].fg);
                // District colours carry meaning, so they're a little stronger than avatar tints.
                const strength = theme.highContrast ? 0 : byDistrict ? (a.depth % 2 ? 0.12 : 0.2) : a.depth % 2 ? 0.07 : 0.13;
                Object.assign(out, {
                    type: "container",
                    color: mix(tint, a.depth % 2 ? theme.spaceFill : theme.groupFill, strength),
                    borderColor: theme.highContrast ? theme.border : mix(tint, theme.bg, 0.35),
                    borderSize: 1,
                });
                if (a.roomId && a.roomId === selected) Object.assign(out, { borderColor: theme.accent, borderSize: 3 });
                return out;
            }

            out.type = "room";
            out.color = !lit ? theme.dim : byDistrict ? districtColour(theme, a.district).bg : theme.decorative[colourIndex(a.roomId ?? a.label)].bg;
            // Faded nodes are plain discs; a photo would stand out more than the search matches.
            if (lit) out.image = avatarUrl?.(a.avatar);
            else out.label = "";

            let ring: string | undefined;
            let glow: string | undefined;
            if (a.highlight) (ring = theme.highlight), (glow = theme.highlight);
            else if (a.unread) (ring = theme.unread), (glow = theme.unread);
            if (a.roomId && a.roomId === current) ring = theme.text;
            if (ring && lit) Object.assign(out, { borderColor: ring, borderSize: 3 });
            if (a.roomId && a.roomId === selected) {
                Object.assign(out, { borderColor: theme.accent, borderSize: 4, zIndex: 1000 });
                glow = theme.accent;
            }
            // Nothing new here: paled, so the rooms with something unread stand out.
            if (anyUnread && !matches && !a.unread && !a.highlight && a.roomId !== current && a.roomId !== selected) {
                Object.assign(out, { quiet: true, veilColor: veil });
            }
            // A thin gap between the ring and the avatar keeps both readable.
            if (out.borderSize) Object.assign(out, { gapSize: 1.5, gapColor: theme.bg });
            if (glow && lit && !theme.highContrast) Object.assign(out, { haloColor: withAlpha(glow, 0.5), haloSpread: 1.3 });
            return out;
        },
    };
}

/** Names fade in as their circle grows, instead of popping. */
function labelDrawers(theme: Theme, colours: () => ColourMode): Record<"drawLabel" | "drawHover", NodeLabelDrawingFunction<NodeAttrs>> {
    const fade = (v: number, from: number, to: number): number => Math.min(1, Math.max(0, (v - from) / (to - from)));
    const drawLabel: NodeLabelDrawingFunction<NodeAttrs> = (ctx, data, s) => {
        if (!data.label) return;
        const attrs = data as Partial<NodeAttrs> & typeof data & { image?: string; quiet?: boolean };
        ctx.save();
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        if (attrs.container) {
            // Space names sit above their circle, outlined in the background colour.
            ctx.globalAlpha = fade(data.size, 22, 40);
            if (ctx.globalAlpha > 0) {
                ctx.font = `600 ${s.labelSize}px ${s.labelFont}`;
                const y = data.y - data.size - 9;
                ctx.lineJoin = "round";
                ctx.lineWidth = 3.5;
                ctx.strokeStyle = theme.bg;
                ctx.strokeText(data.label, data.x, y);
                ctx.fillStyle = theme.text;
                ctx.fillText(data.label, data.x, y);
            }
            // The space's unread messages, on its rim; mentions in red.
            const count = attrs.highlight || attrs.unread;
            ctx.globalAlpha = fade(data.size, 18, 30);
            if (count && ctx.globalAlpha > 0) {
                const r = data.size * Math.SQRT1_2;
                drawBadge(ctx, data.x + r, data.y - r, count, attrs.highlight ? theme.highlight : theme.unread, theme);
            }
        } else if (attrs.image) {
            // Rooms with an avatar: the name in a pill under the circle, so the picture stays visible.
            ctx.globalAlpha = fade(data.size, 12, 22) * (attrs.quiet ? 0.55 : 1);
            if (ctx.globalAlpha > 0) {
                const fontSize = Math.min(14, Math.max(10, data.size / 3));
                ctx.font = `600 ${fontSize}px ${s.labelFont}`;
                const text = truncate(ctx, data.label, Math.max(data.size * 2.4, 80));
                const width = ctx.measureText(text).width;
                const h = fontSize + 6;
                const top = data.y + data.size + 3;
                ctx.fillStyle = theme.labelBg;
                ctx.beginPath();
                ctx.roundRect(data.x - width / 2 - 6, top, width + 12, h, h / 2);
                ctx.fill();
                ctx.fillStyle = theme.text;
                ctx.fillText(text, data.x, top + h / 2);
            }
        } else {
            // The name inside the circle, like the initials in Element's avatars.
            ctx.globalAlpha = fade(data.size, 16, 28) * (attrs.quiet ? 0.55 : 1);
            if (ctx.globalAlpha > 0) {
                ctx.font = `600 ${Math.min(14, Math.max(10, data.size / 3))}px ${s.labelFont}`;
                ctx.fillStyle =
                    colours() === "district" && attrs.district
                        ? districtColour(theme, attrs.district).fg
                        : attrs.roomId
                          ? theme.decorative[colourIndex(attrs.roomId)].fg
                          : theme.text;
                ctx.fillText(truncate(ctx, data.label, data.size * 1.8), data.x, data.y);
            }
        }
        // A room's unread count on its top right (mentions have theirs on the beacon canvas).
        if (!attrs.container && attrs.unread && !attrs.highlight) {
            ctx.globalAlpha = fade(data.size, 7, 12);
            const r = data.size * Math.SQRT1_2;
            if (ctx.globalAlpha > 0) drawBadge(ctx, data.x + r, data.y - r, attrs.unread, theme.unread, theme);
        }
        ctx.restore();
    };
    // Nothing extra on hover: the tooltip has the details.
    return { drawLabel, drawHover: drawLabel };
}

/** A count in a pill centred on (x, y), like Element's notification badges. */
function drawBadge(ctx: CanvasRenderingContext2D, x: number, y: number, count: number, colour: string, theme: Theme): void {
    const text = count > 99 ? "99+" : String(count);
    ctx.save();
    ctx.font = `700 11px ${theme.font}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const h = 17;
    const w = Math.max(h, ctx.measureText(text).width + 10);
    ctx.beginPath();
    ctx.roundRect(x - w / 2, y - h / 2, w, h, h / 2);
    ctx.fillStyle = colour;
    ctx.fill();
    // Outlined in the background colour, to stand off the avatar under it.
    ctx.lineWidth = 2;
    ctx.strokeStyle = theme.bg;
    ctx.stroke();
    ctx.fillStyle = "#fff";
    ctx.fillText(text, x, y + 0.5);
    ctx.restore();
}

function truncate(ctx: CanvasRenderingContext2D, text: string, max: number): string {
    if (ctx.measureText(text).width <= max) return text;
    const chars = Array.from(text);
    while (chars.length && ctx.measureText(chars.join("") + "…").width > max) chars.pop();
    return chars.length ? chars.join("").trimEnd() + "…" : "";
}

/** Same colour pick as Element's avatars (Compound's useIdColorHash). */
export function colourIndex(id: string): number {
    let sum = 0;
    for (let i = 0; i < id.length; i++) sum += id.charCodeAt(i);
    return sum % 6;
}
